def build_registry(tools: Sequence[Tool]) -> Mapping[str, Tool]:
    """Index tools by name. A duplicate name is an error."""
    registry: dict[str, Tool] = {}
    for tool in tools:
        if tool.name in registry:
            raise ValueError(f"duplicate tool name: {tool.name!r}")
